// Bereitet je gefundene Position EIN Item vor
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

const out = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    out.push({
      json: {
        orderId: order.orderId,
        variantId: `gid://shopify/ProductVariant/${pos.variantId}`,
        orderName: order.orderName,
        oldLineItemGid: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`,
        orderGid: `gid://shopify/Order/${order.orderId}`,
        sku: pos.sku
      }
    });
  }
}

return out;

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
}
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) {
  throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));
}

return [{
  json: {
    calcOrderId,
    oldLineItemGid: $('Loop Over Items').item.json.oldLineItemGid,
    orderName: $('Loop Over Items').item.json.orderName,
    orderGid: $('Loop Over Items').item.json.orderGid,
    variantId: $('Loop Over Items').item.json.variantId
  }
}];

const resp = $input.first().json;
const add = resp?.data?.orderEditAddVariant;
const errs = add?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditAddVariant userErrors: ' + JSON.stringify(errs));
}

return [{
  json: {
    calcOrderId: $('CalcOrder auslesen').item.json.calcOrderId,
    orderName: $('CalcOrder auslesen').item.json.orderName,
    oldLineItemGid: $('CalcOrder auslesen').item.json.oldLineItemGid,
    orderGid: $('CalcOrder auslesen').item.json.orderGid,
    addedLineItem: add?.calculatedLineItem || null
  }
}];

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));
}

return [{
  json: {
    status: 'OK',
    orderName: $('Add-Ergebnis prüfen').item.json.orderName,
    committedOrder: commit?.order || null
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

// Beim Testlauf wurde nur die erste Bestellung verarbeitet
const getestet = collected.length ? collected[0] : null;

return [{
  json: {
    hinweis: 'Diese Bestellung wurde im Testlauf korrigiert – in Shopify kontrollieren:',
    orderName: getestet ? getestet.orderName : 'keine Bestellung gefunden',
    orderId: getestet ? getestet.orderId : null
  }
}];

const orderGid = $('Loop Over Items').item.json.orderGid;

const body = {
  query: `mutation orderEditBegin($id: ID!) { orderEditBegin(id: $id) { calculatedOrder { id } userErrors { field message } } }`,
  variables: { id: orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const item = $input.item.json;

const body = {
  query: `mutation orderEditAddVariant($id: ID!, $variantId: ID!, $quantity: Int!, $allowDuplicates: Boolean) {
    orderEditAddVariant(id: $id, variantId: $variantId, quantity: $quantity, allowDuplicates: $allowDuplicates) {
      calculatedLineItem {
        id
        title
        sku
        variantTitle
        discountedUnitPriceSet { shopMoney { amount currencyCode } }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    variantId: item.variantId,
    quantity: 1,
    allowDuplicates: true
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const item = $input.item.json;

const body = {
  query: `mutation orderEditSetQuantity($id: ID!, $lineItemId: ID!, $quantity: Int!, $restock: Boolean) {
    orderEditSetQuantity(id: $id, lineItemId: $lineItemId, quantity: $quantity, restock: $restock) {
      calculatedLineItem { id quantity }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    lineItemId: item.oldLineItemGid,
    quantity: 0,
    restock: false
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const setQty = resp?.data?.orderEditSetQuantity;
const errs = setQty?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditSetQuantity userErrors: ' + JSON.stringify(errs));
}

return {
  json: {
    ...$('Add-Ergebnis prüfen').item.json,
    oldPositionRemoved: true,
    removedLineItem: setQty?.calculatedLineItem || null
  }
};

// Shopify-Standard-Export: eine Zeile pro Line-Item.
// 'Id' steht nur in der ersten Zeile einer Bestellung -> forward-fill ueber 'Name'.
const items = $input.all().map(i => i.json);
let lastId = null;
const seen = new Set();
const orders = [];
for (const row of items) {
  const name = String(row['Name'] || '').trim();
  const idRaw = String(row['Id'] ?? row['ID'] ?? row['id'] ?? '').trim();
  if (idRaw) lastId = idRaw;
  const id = idRaw || lastId;
  if (!id || !name) continue;
  if (seen.has(id)) continue;
  seen.add(id);
  orders.push({ orderId: Number(id), orderName: name });
}
return orders.map(o => ({ json: o }));

// toFix einmalig leeren, Token durchreichen, alle Bestellungen weitergeben.
const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];

const token = $json.access_token;
const orders = $('Bestellungen extrahieren (dedupe)').all().map(i => i.json);

return orders.map(o => ({
  json: { ...o, accessToken: token }
}));

const response = $input.first().json;
const order = response.body?.order || response.order || null;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.toFix)) staticData.toFix = [];

// Zielprodukte aus zentraler Config (Node "Zielprodukte (Config)")
const TARGETS = {};
for (const t of (staticData.targets || [])) {
  TARGETS[String(t.sku).trim()] = { falscherPreis: Number(t.falscherPreis) };
}

if (order) {
  const lineItems = order.line_items || [];
  const matchingLines = lineItems.filter(li => {
    const sku = String(li.sku || '').trim();
    const target = TARGETS[sku];
    if (!target) return false;
    if (Number(li.current_quantity) <= 0) return false;
    return Number(li.price) === target.falscherPreis;
  });
  if (matchingLines.length > 0) {
    staticData.toFix.push({
      orderId: order.id,
      orderName: order.name,
      createdAt: order.created_at,
      positionen: matchingLines.map(li => ({
        lineItemId: li.id,
        title: li.title,
        variantId: li.variant_id,
        sku: li.sku,
        aktuellerPreis: li.price,
        quantity: li.quantity
      }))
    });
  }
}

return [{ json: { collectedCount: staticData.toFix.length } }];

// DEBUG: kompletter Inhalt von staticData.toFix vor der Korrektur
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

if (!collected.length) {
  return [{ json: { WARNUNG: 'toFix ist leer – keine Treffer gefunden', anzahlBestellungen: 0 } }];
}

const rows = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    rows.push({
      json: {
        orderName: order.orderName,
        orderId: order.orderId,
        createdAt: order.createdAt,
        sku: pos.sku,
        title: pos.title,
        lineItemId: pos.lineItemId,
        variantId: pos.variantId,
        aktuellerPreis: pos.aktuellerPreis,
        quantity: pos.quantity,
        // abgeleitete GIDs (so wie sie später in der Korrektur verwendet werden)
        orderGid: `gid://shopify/Order/${order.orderId}`,
        variantGid: `gid://shopify/ProductVariant/${pos.variantId}`,
        oldLineItemGid: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`
      }
    });
  }
}

// Zusammenfassung als erstes Item voranstellen
rows.unshift({
  json: {
    ZUSAMMENFASSUNG: true,
    anzahlBestellungen: collected.length,
    anzahlPositionen: rows.length
  }
});

return rows;

// === HIER PFLEGEN: beliebig viele Zielprodukte ===
// falscherPreis = der fehlerhafte Stückpreis, an dem die Position erkannt wird.
// Der korrekte Preis wird automatisch aus dem aktuellen Shop-Variant-Preis gezogen.
const TARGETS = [
  { sku: 'ZB-2026-08-01', falscherPreis: 24.93 },
];

const staticData = $getWorkflowStaticData('global');
staticData.targets = TARGETS;

// CSV-Binary unverändert durchreichen
return $input.all();

// TESTGATE: verarbeitet nur die erste gefundene Position.
// Für den Vollauf diesen Node deaktivieren oder löschen.
return $input.all().slice(0, 1);
